python3 << 'EOF'
import re

with open('/app/resources/treasury_bulletin_1982_03_page_44.txt', 'r') as f:
    content = f.read()

# Split by <tr><td>
rows = re.split(r'<tr><td>', content)

months = ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']
section = None
total_1982 = 0
items = []

for i, row in enumerate(rows):
    cells = re.split(r'</td><td>', row)
    if len(cells) < 4:
        continue

    # Get first cell
    first_cell = re.sub(r'<[^>]+>', '', cells[0]).strip()

    # Check for year headers
    if first_cell == '1982':
        section = '1982'
        continue
    elif first_cell == '1983':
        section = None
        break

    if section == '1982':
        if not first_cell or 'Total' in first_cell:
            continue

        # Check if first cell starts with a month
        date1 = None
        for m in months:
            if first_cell.startswith(m):
                date1 = m
                break

        if date1:
            total1 = re.sub(r'<[^>]+>', '', cells[3]).strip()
            desc1 = re.sub(r'<[^>]+>', '', cells[1]).strip()

            if total1 and total1 != '*' and total1 != '–':
                try:
                    total1_val = int(total1.replace(',', ''))
                    total_1982 += total1_val
                    items.append((date1, desc1, total1_val))
                except:
                    pass

            # Second security in row
            if len(cells) >= 12:
                date2_check = re.sub(r'<[^>]+>', '', cells[6]).strip()
                date2 = None
                for m in months:
                    if date2_check.startswith(m):
                        date2 = m
                        break

                if date2:
                    total2 = re.sub(r'<[^>]+>', '', cells[9]).strip()
                    desc2 = re.sub(r'<[^>]+>', '', cells[7]).strip()

                    if total2 and total2 != '*' and total2 != '–':
                        try:
                            total2_val = int(total2.replace(',', ''))
                            total_1982 += total2_val
                            items.append((date2, desc2, total2_val))
                        except:
                            pass

print(f"Total 1982 securities: ${total_1982:,} million")
print(f"\nNumber of items: {len(items)}")
print("\nAll items:")
for item in items:
    print(f"  {item}")
